        SCORE += scoreAmount;
        SaveScore();
    }

    private void SaveScore()
    {
        PlayerPrefs.SetInt("Score", SCORE);
    }

    private void LoadScore()
    {
        SCORE = PlayerPrefs.GetInt("Score", 0); // Load the current score
    }

    public void Die()
    {
        IsGameOver = true; // Toggle the gameOver flag
        SCORE = 0; // Reset the score
        SaveScore(); // Save the new score
    }
}
```

